import{_ as o,C as i,o as e,c as s,a2 as a,b as l,w as n,a as d,E as c,a3 as g}from"./chunks/framework.RycU2wFZ.js";const A=JSON.parse('{"title":"AgentPay Security & Threat Model Specification (v0)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/security-model.md","filePath":"zh/specs/security-model.md","lastUpdated":null}'),u={name:"zh/specs/security-model.md"};function p(h,t,y,f,m,x){const r=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="agentpay-security-threat-model-specification-v0" tabindex="-1">AgentPay Security &amp; Threat Model Specification (v0) <a class="header-anchor" href="#agentpay-security-threat-model-specification-v0" aria-label="Permalink to &quot;AgentPay Security &amp; Threat Model Specification (v0)&quot;">​</a></h1><blockquote><p><strong>Specification Version:</strong> 1.1.0 (Public Threat Model v0)<br><strong>Status:</strong> Production Specification<br><strong>Target Runtimes:</strong> Python SDK (<code>agentpay</code>), Go Gateway (<code>gateway-go</code>)</p></blockquote><hr><h2 id="_1-system-context-trust-boundaries" tabindex="-1">1. System Context &amp; Trust Boundaries <a class="header-anchor" href="#_1-system-context-trust-boundaries" aria-label="Permalink to &quot;1. System Context &amp; Trust Boundaries&quot;">​</a></h2><p>AgentPay operates at the boundary between non-deterministic Large Language Models (LLMs) and deterministic cryptographic financial networks.</p>',5)),(e(),l(g,null,{default:n(()=>[c(r,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20UntrustedZone%20%5BUNTRUSTED%20ZONE%5D%0A%20%20%20%20%20%20%20%20LLM%5BLLM%20Agent%20Core%20%2F%20Prompt%5D%0A%20%20%20%20%20%20%20%20ContextMem%5BPrompt%20Context%20%26%20Tool%20Outputs%5D%0A%20%20%20%20%20%20%20%20PublicWeb%5BExternal%20Web%20%2F%20Third-Party%20APIs%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20BuyerHost%20%5BBUYER%20HOST%20TRUST%20BOUNDARY%5D%0A%20%20%20%20%20%20%20%20Interceptor%5BAgentPay%20HTTP%20Interceptor%5D%0A%20%20%20%20%20%20%20%20Firewall%5BFinancial%20Firewall%20%2F%20Policy%20Engine%5D%0A%20%20%20%20%20%20%20%20DB%5B(Local%20SQLite%20Policy%20Ledger)%5D%0A%20%20%20%20%20%20%20%20Signer%5BLocalSigner%20Keystore%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SellerDomain%20%5BSELLER%20%2F%20GATEWAY%20DOMAIN%5D%0A%20%20%20%20%20%20%20%20Gateway%5BAgentPay%20Self-Hosted%20Gateway%5D%0A%20%20%20%20%20%20%20%20Upstream%5BInternal%20Business%20Upstream%20API%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SettlementLayer%20%5BSETTLEMENT%20LAYER%5D%0A%20%20%20%20%20%20%20%20Facilitator%5BFacilitator%20Service%5D%0A%20%20%20%20%20%20%20%20Chain%5B(EVM%20Blockchain%20%2F%20Base)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20LLM%20--%3E%7CPrompt%20Output%20%2F%20Unchecked%20Action%7C%20Interceptor%0A%20%20%20%20ContextMem%20-.-%3E%7CPotential%20Prompt%20Injection%7C%20Interceptor%0A%20%20%20%20Interceptor%20--%3E%7C1.%20Check%20%26%20Reserve%7C%20Firewall%0A%20%20%20%20Firewall%20--%3E%7CAtomic%20Tx%20%26%20Quota%20Lock%7C%20DB%0A%20%20%20%20Firewall%20--%3E%7C2.%20Approved%20Challenge%7C%20Signer%0A%20%20%20%20Signer%20--%3E%7C3.%20EIP-712%20%2F%20EIP-3009%20Signature%7C%20Interceptor%0A%20%20%20%20Interceptor%20--%3E%7C4.%20HTTP%20%2B%20PAYMENT-SIGNATURE%7C%20Gateway%0A%20%20%20%20Gateway%20--%3E%7C5.%20Verify%20Signature%7C%20Facilitator%0A%20%20%20%20Gateway%20--%3E%7C6.%20Reverse%20Proxy%20Dispatch%7C%20Upstream%0A%20%20%20%20Facilitator%20--%3E%7C7.%20Batch%20Gasless%20Settle%7C%20Chain%0A%0A%20%20%20%20style%20UntrustedZone%20fill%3A%23ffebee%2Cstroke%3A%23c62828%2Cstroke-width%3A2px%0A%20%20%20%20style%20BuyerHost%20fill%3A%23e8f5e9%2Cstroke%3A%232e7d32%2Cstroke-width%3A2px%0A%20%20%20%20style%20SellerDomain%20fill%3A%23e3f2fd%2Cstroke%3A%231565c0%2Cstroke-width%3A2px%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h3 id="trust-matrix" tabindex="-1">Trust Matrix <a class="header-anchor" href="#trust-matrix" aria-label="Permalink to &quot;Trust Matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Actor / Component</th><th style="text-align:center;">Trust Level</th><th style="text-align:left;">Rationale</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LLM Agent &amp; Prompt Context</strong></td><td style="text-align:center;">❌ <strong>Untrusted</strong></td><td style="text-align:left;">Susceptible to prompt injection, jailbreaking, and hallucination. Must never hold or see raw private keys.</td></tr><tr><td style="text-align:left;"><strong>Policy Engine (Firewall)</strong></td><td style="text-align:center;">🛡️ <strong>Trusted</strong></td><td style="text-align:left;">In-process deterministic code executing independently of model tokens.</td></tr><tr><td style="text-align:left;"><strong>Local SQLite Ledger</strong></td><td style="text-align:center;">🛡️ <strong>Trusted</strong></td><td style="text-align:left;">Local filesystem storage operating under exclusive file locks (<code>WAL</code> + <code>BEGIN IMMEDIATE</code>).</td></tr><tr><td style="text-align:left;"><strong>LocalSigner / Wallet</strong></td><td style="text-align:center;">🛡️ <strong>Trusted</strong></td><td style="text-align:left;">Memory-isolated signer; only signs pre-evaluated, valid EIP-712 payloads.</td></tr><tr><td style="text-align:left;"><strong>Self-Hosted Gateway</strong></td><td style="text-align:center;">⚖️ <strong>Semi-Trusted</strong></td><td style="text-align:left;">Enforces price quotes and proxies requests; verified via Facilitator and HMAC hashes.</td></tr><tr><td style="text-align:left;"><strong>External API / Third-Party Upstream</strong></td><td style="text-align:center;">❌ <strong>Untrusted</strong></td><td style="text-align:left;">Could return exorbitant 402 quotes, spoof headers, or drop connections post-payment.</td></tr><tr><td style="text-align:left;"><strong>Facilitator Node</strong></td><td style="text-align:center;">⚖️ <strong>Semi-Trusted</strong></td><td style="text-align:left;">Verifies and batches signatures on-chain. Cannot steal funds because authorizations are payee-pinned.</td></tr></tbody></table><hr><h2 id="_2-in-scope-threats-defenses-buyer-domain-what-is-defended" tabindex="-1">2. In-Scope Threats &amp; Defenses (Buyer Domain - What Is Defended) <a class="header-anchor" href="#_2-in-scope-threats-defenses-buyer-domain-what-is-defended" aria-label="Permalink to &quot;2. In-Scope Threats &amp; Defenses (Buyer Domain - What Is Defended)&quot;">​</a></h2><p>The v0 security architecture explicitly defends the Buyer against 7 threat vectors:</p><h3 id="t1-financial-prompt-injection-self-granting" tabindex="-1">T1: Financial Prompt Injection &amp; Self-Granting <a class="header-anchor" href="#t1-financial-prompt-injection-self-granting" aria-label="Permalink to &quot;T1: Financial Prompt Injection &amp; Self-Granting&quot;">​</a></h3><ul><li><strong>Defense:</strong> LLM context possesses zero programmatic hooks to alter policy files, SQLite tables, or budget configurations. All checks execute via in-process deterministic Python code before invoking the private key.</li></ul><h3 id="t2-runaway-agent-infinite-loop-drain" tabindex="-1">T2: Runaway Agent Infinite-Loop Drain <a class="header-anchor" href="#t2-runaway-agent-infinite-loop-drain" aria-label="Permalink to &quot;T2: Runaway Agent Infinite-Loop Drain&quot;">​</a></h3><ul><li><strong>Defense:</strong> Rolling RPM frequency circuit breaker (e.g. max 15 req/min) + hard 24h rolling budget pool. Trips to <code>OPEN</code> state upon burst detection.</li></ul><h3 id="t3-rogue-upstream-quote-gouging-price-creep-p1-7" tabindex="-1">T3: Rogue Upstream Quote Gouging &amp; Price Creep (P1-7) <a class="header-anchor" href="#t3-rogue-upstream-quote-gouging-price-creep-p1-7" aria-label="Permalink to &quot;T3: Rogue Upstream Quote Gouging &amp; Price Creep (P1-7)&quot;">​</a></h3><ul><li><strong>Defense:</strong> Hard <code>max_per_tx_base_units</code> integer comparison + strict payee/asset/network whitelisting. Optionally enforces resource price ceilings against sudden price inflation.</li></ul><h3 id="t4-cross-chain-cross-contract-replay-attacks" tabindex="-1">T4: Cross-Chain &amp; Cross-Contract Replay Attacks <a class="header-anchor" href="#t4-cross-chain-cross-contract-replay-attacks" aria-label="Permalink to &quot;T4: Cross-Chain &amp; Cross-Contract Replay Attacks&quot;">​</a></h3><ul><li><strong>Defense:</strong> EIP-712 domain separator cryptographically binds <code>chainId</code> (e.g., <code>84532</code>) and <code>verifyingContract</code> (token address).</li></ul><h3 id="t5-signature-replay-double-spending" tabindex="-1">T5: Signature Replay &amp; Double-Spending <a class="header-anchor" href="#t5-signature-replay-double-spending" aria-label="Permalink to &quot;T5: Signature Replay &amp; Double-Spending&quot;">​</a></h3><ul><li><strong>Defense:</strong> EIP-3009 32-byte secure random nonce generated via <code>secrets.token_bytes(32)</code>. Gateway enforces unique <code>(network, asset, payer, nonce)</code>.</li></ul><h3 id="t6-delayed-submission-arbitrage-hold" tabindex="-1">T6: Delayed Submission &amp; Arbitrage Hold <a class="header-anchor" href="#t6-delayed-submission-arbitrage-hold" aria-label="Permalink to &quot;T6: Delayed Submission &amp; Arbitrage Hold&quot;">​</a></h3><ul><li><strong>Defense:</strong> Authorizations enforce strict expiration: $\\text{validBefore} = \\text{validAfter} + 300\\text{s}$. Expired authorizations are mathematically invalid on-chain.</li></ul><h3 id="t7-concurrent-budget-race-conditions" tabindex="-1">T7: Concurrent Budget Race Conditions <a class="header-anchor" href="#t7-concurrent-budget-race-conditions" aria-label="Permalink to &quot;T7: Concurrent Budget Race Conditions&quot;">​</a></h3><ul><li><strong>Defense:</strong> Evaluated and locked inside an exclusive SQLite transaction (<code>BEGIN IMMEDIATE</code>). Quota is moved to <code>RESERVED</code> before signing.</li></ul><hr><h2 id="_3-gateway-security-inbound-threat-defenses-gateway-domain-p0-5" tabindex="-1">3. Gateway Security &amp; Inbound Threat Defenses (Gateway Domain, P0-5) <a class="header-anchor" href="#_3-gateway-security-inbound-threat-defenses-gateway-domain-p0-5" aria-label="Permalink to &quot;3. Gateway Security &amp; Inbound Threat Defenses (Gateway Domain, P0-5)&quot;">​</a></h2><p>The self-hosted gateway explicitly defends against the following 5 seller-side threats:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Threat Category</th><th style="text-align:left;">Description</th><th style="text-align:left;">Primary Defense</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>G1: Front-Running Drain / Cancel Attack</strong></td><td style="text-align:left;">In &quot;optimistic delivery&quot;, buyer receives data before settlement. A rogue buyer immediately transfers funds away or invokes <code>cancelAuthorization</code>.</td><td style="text-align:left;">1. Gateway queries node RPC for buyer token balance during verification.<br>2. High-value routes offer <code>settle_before_deliver: true</code>.<br>3. Low-value micro-transactions accept small default risk.</td></tr><tr><td style="text-align:left;"><strong>G2: Idempotency Cache Hijacking</strong></td><td style="text-align:left;">An attacker guesses or sniffs an <code>Idempotency-Key</code> and fetches paid response without paying.</td><td style="text-align:left;">Cache is strictly bound to <code>(payer_address, idempotency_key)</code>. Replay requests MUST carry a signature from the same <code>payer_address</code>.</td></tr><tr><td style="text-align:left;"><strong>G3: SSRF &amp; Internal Network Exposure</strong></td><td style="text-align:left;">Malicious HTTP requests attempt path traversal or internal IP routing via reverse proxy.</td><td style="text-align:left;">1. Gateway routes defined strictly via static YAML upstream URLs.<br>2. Strips hop-by-hop headers and internal auth tokens.<br>3. Disallows HTTP redirects (<code>follow_redirects=False</code>) to private subnets.</td></tr><tr><td style="text-align:left;"><strong>G4: 402 Challenge &amp; Facilitator DoS Flood</strong></td><td style="text-align:left;">Attackers spam unauthenticated requests to exhaust Facilitator quota or CPU.</td><td style="text-align:left;">1. Inbound IP rate limiting on 402 challenge generation.<br>2. Gateway employs circuit breaker on outgoing Facilitator <code>/v1/verify</code> calls.</td></tr><tr><td style="text-align:left;"><strong>G5: Configuration Tampering</strong></td><td style="text-align:left;">Local file tampering with route prices or payee addresses.</td><td style="text-align:left;">Gateway YAML configuration loaded with read-only permissions (<code>chmod 400</code>) and validated on startup.</td></tr></tbody></table><hr><h2 id="_4-explicit-non-goals-for-v0-what-is-not-defended-p0-4-p1-10" tabindex="-1">4. Explicit Non-Goals for v0 (What Is Not Defended, P0-4, P1-10) <a class="header-anchor" href="#_4-explicit-non-goals-for-v0-what-is-not-defended-p0-4-p1-10" aria-label="Permalink to &quot;4. Explicit Non-Goals for v0 (What Is Not Defended, P0-4, P1-10)&quot;">​</a></h2><p>The following threats are <strong>EXPLICITLY OUT OF SCOPE</strong> for the v0 milestone:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Threat Category</th><th style="text-align:center;">Status in v0</th><th style="text-align:left;">Explanation &amp; 2027 Mitigation Plan</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>N1: Host Machine Root Compromise</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">If an attacker has root access or reads memory, they can extract plaintext keys from <code>LocalSigner</code>.<br><em>2027 Plan:</em> Hardware security modules (HSM) and Cloud KMS signers.</td></tr><tr><td style="text-align:left;"><strong>N2: Economic Waste within Budget Quota</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">If an agent spends $0.001 within allowed budget on a whitelisted API that produces useless answers, AgentPay cannot judge semantic quality.</td></tr><tr><td style="text-align:left;"><strong>N3: Semantic Data Quality / Garbage Upstream</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">If an upstream API returns HTTP 200 with invalid or hallucinated data, AgentPay verifies payment delivery, not content truthfulness.</td></tr><tr><td style="text-align:left;"><strong>N4: Facilitator Complete Denial of Service (DoS)</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">If all Facilitator nodes go offline, transactions cannot settle on-chain. Buyer funds are safe (not stolen), but payment flow halts.</td></tr><tr><td style="text-align:left;"><strong>N5: Unsupported Token Contracts</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">Tokens that lack native EIP-3009 (<code>transferWithAuthorization</code>) support cannot be settled gaslessly. v0 strictly targets standard USDC-compatible contracts.</td></tr><tr><td style="text-align:left;"><strong>N6: Malicious In-Process Tools (P0-4)</strong></td><td style="text-align:center;">❌ <strong>Not Protected</strong></td><td style="text-align:left;">In the v0 embedded library mode, the LLM runtime and the SDK share a Python process. A tool with arbitrary code execution (<code>eval</code>) or arbitrary file read/write can bypass the interceptor.<br><em>2027 Plan:</em> Isolated out-of-process local sidecar daemon running under a dedicated OS user.</td></tr></tbody></table><hr><h2 id="_5-fundamental-invariants-operational-rules" tabindex="-1">5. Fundamental Invariants &amp; Operational Rules <a class="header-anchor" href="#_5-fundamental-invariants-operational-rules" aria-label="Permalink to &quot;5. Fundamental Invariants &amp; Operational Rules&quot;">​</a></h2><h3 id="invariant-1-anti-overspend-rule-p0-1-p1-9" tabindex="-1">Invariant 1: Anti-Overspend Rule (P0-1, P1-9) <a class="header-anchor" href="#invariant-1-anti-overspend-rule-p0-1-p1-9" aria-label="Permalink to &quot;Invariant 1: Anti-Overspend Rule (P0-1, P1-9)&quot;">​</a></h3><ul><li>Once an intent enters <code>SIGNATURE_SENT</code>, network failure <strong>CANNOT</strong> automatically trigger quota release. Quota remains <code>RESERVED</code> until <code>now &gt; validBefore + 60s</code> <strong>AND</strong> on-chain authorization state is proven unspent.</li></ul><h3 id="invariant-2-single-ledger-invariant-p0-4" tabindex="-1">Invariant 2: Single-Ledger Invariant (P0-4) <a class="header-anchor" href="#invariant-2-single-ledger-invariant-p0-4" aria-label="Permalink to &quot;Invariant 2: Single-Ledger Invariant (P0-4)&quot;">​</a></h3><ul><li><strong>One private key corresponds to exactly one SQLite ledger file.</strong> Running multiple Agent processes using the same wallet key against separate SQLite files will result in budget multiplication and is strictly prohibited.</li></ul><h3 id="invariant-3-fail-closed-default" tabindex="-1">Invariant 3: Fail-Closed Default <a class="header-anchor" href="#invariant-3-fail-closed-default" aria-label="Permalink to &quot;Invariant 3: Fail-Closed Default&quot;">​</a></h3><ul><li>In any circumstance of database lock failure, serialization error, or unhandled exception within the Policy Engine, <strong>the transaction MUST default to REJECTED</strong>.</li></ul>',35))])}const P=o(u,[["render",p]]);export{A as __pageData,P as default};
